-- EGOY PREMIUM - REFERENCE-IMAGE UI
-- Uses the supplied reference artwork as the actual GUI background.
-- EGOY license validation uses POST JSON through the available HTTP request function.

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")

local Player = Players.LocalPlayer
if not Player then return end

local IMAGE_FILE = "EGOY_REFERENCE_UI.jpg"

local IMAGE_B64 = [[

]]


local function base64decode(data)
    local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    data = data:gsub('[^' .. b .. '=]', '')
    return (data:gsub('.', function(x)
        if x == '=' then return '' end
        local r, f = '', (b:find(x, 1, true) or 1) - 1
        for i = 6, 1, -1 do
            r = r .. ((f % 2^i - f % 2^(i-1) > 0) and '1' or '0')
        end
        return r
    end):gsub('%d%d%d?%d?%d?%d?%d?%d?', function(x)
        if #x ~= 8 then return '' end
        local c = 0
        for i = 1, 8 do
            c = c + (x:sub(i,i) == '1' and 2^(8-i) or 0)
        end
        return string.char(c)
    end))
end


-- Write the supplied reference image to the executor's asset folder.
local function loadReferenceImage()
    if typeof(writefile) ~= "function" then
        return nil, "writefile is unavailable"
    end

    local ok, bytes = pcall(base64decode, IMAGE_B64)
    if not ok or not bytes then
        return nil, "image decode failed"
    end

    local wrote = pcall(function()
        writefile(IMAGE_FILE, bytes)
    end)

    if not wrote then
        return nil, "could not write reference image"
    end

    local assetFn = nil
    if typeof(getcustomasset) == "function" then
        assetFn = getcustomasset
    elseif typeof(getsynasset) == "function" then
        assetFn = getsynasset
    end

    if not assetFn then
        return nil, "custom asset function unavailable"
    end

    local ok2, asset = pcall(function()
        return assetFn(IMAGE_FILE)
    end)

    if not ok2 or not asset then
        return nil, "could not load reference image"
    end

    return asset
end

local function getGuiParent()
    -- PlayerGui is the most compatible fallback.
    local pg = Player:WaitForChild("PlayerGui")
    return pg
end

local parent = getGuiParent()

local old = parent:FindFirstChild("EGOY_REFERENCE_LOGIN")
if old then old:Destroy() end

local gui = Instance.new("ScreenGui")
gui.Name = "EGOY_REFERENCE_LOGIN"
gui.ResetOnSpawn = false
gui.IgnoreGuiInset = true
gui.DisplayOrder = 999999
gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
gui.Parent = parent

local root = Instance.new("Frame")
root.AnchorPoint = Vector2.new(0.5, 0.5)
root.Position = UDim2.fromScale(0.5, 0.5)
root.Size = UDim2.new(0.94, 0, 0.88, 0)
root.BackgroundTransparency = 1
root.Parent = gui

local aspect = Instance.new("UIAspectRatioConstraint")
aspect.AspectRatio = 1463 / 1007
aspect.DominantAxis = Enum.DominantAxis.Width
aspect.Parent = root

local reference = Instance.new("ImageLabel")
reference.Name = "ExactReferenceArtwork"
reference.Size = UDim2.fromScale(1, 1)
reference.Position = UDim2.fromScale(0, 0)
reference.BackgroundTransparency = 1
reference.ScaleType = Enum.ScaleType.Stretch
reference.ZIndex = 1
reference.Parent = root

local asset, assetError = loadReferenceImage()
if asset then
    reference.Image = asset
else
    -- If custom assets aren't supported, keep the GUI alive and report the exact reason.
    warn("[EGOY] Reference artwork unavailable: " .. tostring(assetError))
end

-- Transparent interaction layer over the reference's top-right controls.
local controls = Instance.new("Frame")
controls.BackgroundTransparency = 1
controls.Position = UDim2.new(0.735, 0, 0.075, 0)
controls.Size = UDim2.new(0.215, 0, 0.105, 0)
controls.ZIndex = 20
controls.Parent = root

local controlLayout = Instance.new("UIListLayout")
controlLayout.FillDirection = Enum.FillDirection.Horizontal
controlLayout.HorizontalAlignment = Enum.HorizontalAlignment.Right
controlLayout.VerticalAlignment = Enum.VerticalAlignment.Center
controlLayout.Padding = UDim.new(0.035, 0)
controlLayout.Parent = controls

local function invisibleButton(name, text)
    local b = Instance.new("TextButton")
    b.Name = name
    b.BackgroundTransparency = 1
    b.Text = text
    b.TextTransparency = 1
    b.AutoButtonColor = false
    b.Size = UDim2.fromScale(0.30, 1)
    b.ZIndex = 21
    b.Parent = controls
    return b
end

local minimize = invisibleButton("Minimize", "−")
local maximize = invisibleButton("Maximize", "□")
local close = invisibleButton("Close", "×")

-- License/login system removed.
-- The reference UI loads directly without key redemption or license-server calls.

-- Functional drag using the reference's header area.
local dragging = false
local dragStart
local startPosition

local dragArea = Instance.new("TextButton")
dragArea.BackgroundTransparency = 1
dragArea.Text = ""
dragArea.AutoButtonColor = false
dragArea.Position = UDim2.fromScale(0.02, 0.02)
dragArea.Size = UDim2.fromScale(0.70, 0.23)
dragArea.ZIndex = 5
dragArea.Parent = root

dragArea.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        dragging = true
        dragStart = input.Position
        startPosition = root.Position
    end
end)

dragArea.InputEnded:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton1
        or input.UserInputType == Enum.UserInputType.Touch then
        dragging = false
    end
end)

UserInputService.InputChanged:Connect(function(input)
    if not dragging then return end
    if input.UserInputType ~= Enum.UserInputType.MouseMovement
        and input.UserInputType ~= Enum.UserInputType.Touch then
        return
    end

    local delta = input.Position - dragStart
    root.Position = UDim2.new(
        startPosition.X.Scale,
        startPosition.X.Offset + delta.X,
        startPosition.Y.Scale,
        startPosition.Y.Offset + delta.Y
    )
end)

close.MouseButton1Click:Connect(function()
    gui:Destroy()
end)

minimize.MouseButton1Click:Connect(function()
    reference.Visible = not reference.Visible
end)

maximize.MouseButton1Click:Connect(function()
    root.Size = UDim2.new(0.98, 0, 0.92, 0)
end)

print("[EGOY] Reference UI loaded.")
print("[EGOY] UserId:", Player.UserId)
